import { Link, useParams } from 'react-router-dom';
import { useEffect } from 'react';
import { Logo } from '@/components/Logo';
import { trackEvent, trackPageView } from '@/lib/analytics';
import guides from '@/lib/seoGuides.json';
import NotFound from '@/pages/NotFound';

export default function GuidePage() {
  const { guideSlug } = useParams();
  const guide = guides[guideSlug];
  useEffect(() => {
    if (guide) trackPageView('guide');
  }, [guideSlug, guide]);
  if (!guide) return <NotFound />;

  return <div className="min-h-screen bg-[#fbf7ef] text-[#2c4c3b] overflow-x-hidden">
    <header className="border-b border-[#e5d9c3] bg-[#fbf7ef]">
      <nav aria-label="Main navigation" className="max-w-5xl mx-auto px-5 py-3 flex flex-wrap items-center justify-between gap-3">
        <Link to="/" aria-label="AYANA home"><Logo size={38} /></Link>
        <div className="flex flex-wrap gap-4 text-sm font-semibold"><Link to="/">Home</Link><a href="/#how">How it works</a><Link to="/about">About</Link><Link to="/signup" onClick={() => trackEvent('cta_click', { id: 'guide-header', guide: guideSlug })}>Get started</Link></div>
      </nav>
    </header>
    <main className="max-w-5xl mx-auto px-5 py-10 sm:py-16">
      <p className="text-sm uppercase tracking-widest text-[#856719]">AYANA family guide</p>
      <h1 className="font-serif text-4xl sm:text-5xl leading-tight max-w-3xl mt-3">{guide.heading}</h1>
      <p className="text-lg leading-relaxed max-w-3xl mt-6">{guide.intro}</p>
      <img src={guide.image} alt={guide.imageAlt} width="1200" height="800" className="w-full max-h-[460px] object-cover rounded-2xl mt-8" />
      <div className="grid md:grid-cols-3 gap-6 mt-12">{guide.sections.map(section => <section key={section.heading} className="rounded-xl bg-white p-6 border border-[#e5d9c3]"><h2 className="font-serif text-2xl">{section.heading}</h2><p className="mt-3 leading-relaxed">{section.body}</p></section>)}</div>
      <section className="max-w-3xl mt-14"><h2 className="font-serif text-3xl">Common questions</h2>{guide.questions.map(item => <div key={item.question} className="border-b border-[#e5d9c3] py-5"><h3 className="font-semibold">{item.question}</h3><p className="mt-2 leading-relaxed">{item.answer}</p></div>)}</section>
      <div className="mt-14 rounded-2xl bg-[#2c4c3b] text-white p-7 sm:p-10"><h2 className="font-serif text-3xl">Plan a routine that fits your family</h2><p className="mt-3 max-w-2xl">See how AYANA works, review the plan options, and set up check-ins only with your parent's knowledge and consent.</p><Link to="/signup" onClick={() => trackEvent('cta_click', { id: 'guide-primary', guide: guideSlug })} className="inline-block mt-6 rounded-full bg-white text-[#2c4c3b] px-6 py-3 font-semibold">Get started</Link></div>
      <nav aria-label="More family guides" className="flex flex-wrap gap-4 mt-10 text-sm underline">{Object.entries(guides).filter(([slug]) => slug !== guideSlug).map(([slug, value]) => <Link key={slug} to={`/${slug}`}>{value.heading}</Link>)}</nav>
    </main>
    <footer className="border-t border-[#e5d9c3] px-5 py-8 text-center text-sm"><p>© {new Date().getFullYear()} AYANA · <Link to="/privacy" className="underline">Privacy</Link> · <Link to="/terms" className="underline">Terms</Link> · <a href="mailto:admin@ayanabott.com" className="underline">Email us</a></p><p className="mt-2">AYANA is a family communication service, not a medical or emergency service.</p></footer>
  </div>;
}
